import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        StringBuilder outputStr = new StringBuilder();
        outputStr.append(inputStr.charAt(0));
        boolean replaced = false;
        int index = 1;
        int len = inputStr.length();

        while (index < len) {
            if (!replaced && index < len - 2 && inputStr.charAt(index) == 'a' && inputStr.charAt(index + 1) == 't') {
                outputStr.append("@");
                replaced = true;
                index++;
            } else if (index + 2 < len && inputStr.substring(index, index + 3).equals("dot")) {
                outputStr.append(".");
                index += 2;
            } else {
                outputStr.append(inputStr.charAt(index));
            }
            index++;
        }
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
